import test from 'node:test';
import assert from 'node:assert/strict';
import {JSDOM} from 'jsdom';
import {STORIES,CHOICES_KEY,createChoices,choose,hintChoices,nextChoice,validateChoices,saveChoices,loadChoices} from './choices-engine.js';
import {mountChoices,storyArt} from './choices.js';
const complete=(wrong=0)=>{let s=createChoices({id:'round-1'});for(const [i,q]of STORIES.entries()){if(i<wrong)s=choose(s,q.options.find(o=>o.id!==q.answer).id).state;s=nextChoice(choose(s,q.answer).state);}return s;};
test('ten stories have one authored answer, varied positions and meaningful visual outcomes',()=>{assert.equal(STORIES.length,10);assert.equal(new Set(STORIES.map(q=>q.id)).size,10);assert.equal(new Set(STORIES.map(q=>q.options.findIndex(o=>o.id===q.answer))).size,3);for(const q of STORIES){assert.equal(q.options.filter(o=>o.id===q.answer).length,1);assert.ok(q.options.every(o=>o.reply.length>20));assert.match(storyArt(q,true),/is-solved/);assert.notEqual(storyArt(q),storyArt(q,true));}});
test('all ten right first time is 10/10 and 150 Sparks',()=>{const s=complete();assert.equal(s.firstCorrect,10);assert.equal(s.points,150);assert.equal(s.complete,true);assert.equal(validateChoices(s).firstCorrect,10);});
for(const misses of [1,5,9,10])test(`${misses} retries preserve honest first-attempt score`,()=>{const s=complete(misses);assert.equal(s.firstCorrect,10-misses);assert.equal(s.points,150-5*misses);assert.equal(s.attempts.length,10+misses);assert.equal(validateChoices(s).points,s.points);});
test('correct choice is locked until explicit Next, and repeated taps earn nothing',()=>{const start=createChoices();assert.equal(nextChoice(start),start);let r=choose(start,STORIES[0].answer);assert.equal(r.state.index,0);assert.equal(r.state.solved,true);assert.equal(choose(r.state,STORIES[0].answer).accepted,false);assert.equal(nextChoice(r.state).index,1);});
test('hint stays in parent record and does not earn the unaided bonus',()=>{let s=hintChoices(createChoices());s=hintChoices(s);assert.deepEqual(s.hints,['speaker']);s=choose(s,'share').state;assert.equal(s.points,10);assert.equal(s.firstCorrect,1);assert.deepEqual(validateChoices(s).hints,['speaker']);});
test('storage replays correctness and rejects skipped or fabricated answers',()=>{let s=complete(5);s.points=9999;s.firstCorrect=10;s.attempts[0].correct=true;assert.equal(validateChoices(s).points,125);assert.equal(validateChoices(s).firstCorrect,5);assert.equal(validateChoices({...s,attempts:s.attempts.slice(1,3),index:8}),null);assert.equal(validateChoices({...createChoices(),attempts:[{storyId:'speaker',answer:'magic'}]}),null);});
test('storage bounds history and failures never block play',()=>{const data=new Map(),storage={getItem:k=>data.get(k),setItem:(k,v)=>data.set(k,v)};saveChoices(storage,Array.from({length:25},(_,i)=>({...complete(),id:'r'+i})));assert.equal(loadChoices(storage).length,20);data.set(CHOICES_KEY,'{bad');assert.deepEqual(loadChoices(storage),[]);assert.equal(saveChoices({setItem(){throw Error('full')}},[complete()]),false);});
function setup(route='learn?game=choices'){const dom=new JSDOM('<body><div id="game"></div></body>',{url:'http://localhost'});dom.window.matchMedia=()=>({matches:false});const host=dom.window.document.querySelector('#game');const cleanup=mountChoices(host,{route,storage:dom.window.localStorage});return{dom,host,cleanup,click:selector=>{const b=host.querySelector(selector);assert.ok(b,selector);b.click();}};}
test('wrong answer shows a cross and explanation; correction changes scene and exposes Next',()=>{const t=setup();t.click('[data-cc-answer="bin"]');assert.match(t.host.textContent,/Not yet/);assert.ok(t.host.querySelector('.cc-wrong-sign'));assert.equal(t.host.querySelector('[data-cc-next]'),null);t.click('[data-cc-answer="share"]');assert.ok(t.host.querySelector('.is-solved'));assert.match(t.host.textContent,/10 Sparks/);assert.equal(t.dom.window.document.activeElement,t.host.querySelector('[data-cc-next]'));t.click('[data-cc-next]');assert.match(t.host.textContent,/STORY 2 OF 10/);t.cleanup();t.dom.window.close();});
test('completed visual result survives remount before Next without doubling points',()=>{const t=setup();t.click('[data-cc-answer="share"]');t.cleanup();const cleanup=mountChoices(t.host,{storage:t.dom.window.localStorage});assert.ok(t.host.querySelector('[data-cc-next]'));assert.match(t.host.textContent,/15/);assert.ok(t.host.querySelector('.is-solved'));cleanup();t.dom.window.close();});
test('all ten stories finish with 5/10 and exact wrong choices shown to parents',()=>{const t=setup();for(const [i,q]of STORIES.entries()){if(i<5)t.click(`[data-cc-answer="${q.options.find(o=>o.id!==q.answer).id}"]`);t.click(`[data-cc-answer="${q.answer}"]`);t.click('[data-cc-next]');}assert.match(t.host.textContent,/5\/10/);assert.match(t.host.textContent,/worked through all 10/);t.cleanup();const cleanup=mountChoices(t.host,{route:'parents?view=choices',storage:t.dom.window.localStorage});assert.equal(t.host.querySelectorAll('.cc-record article').length,10);assert.match(t.host.textContent,/✕ Tried: Put it in the bin/);assert.match(t.host.textContent,/Talk together:/);assert.equal(t.dom.window.document.body.classList.contains('ff-game-mode'),false);cleanup();t.dom.window.close();});
test('motion control works and abort removes listeners and game chrome',()=>{const t=setup();t.click('[data-cc-motion]');assert.ok(t.host.classList.contains('cc-paused'));t.cleanup();assert.equal(t.dom.window.document.body.classList.contains('ff-game-mode'),false);const text=t.host.textContent;t.click('[data-cc-answer="bin"]');assert.equal(t.host.textContent,text);t.dom.window.close();});
test('parent record includes a hint-only story before any answer',()=>{const t=setup();t.click('[data-cc-hint]');t.cleanup();const cleanup=mountChoices(t.host,{route:'parents?view=choices',storage:t.dom.window.localStorage});assert.equal(t.host.querySelectorAll('.cc-record article').length,1);assert.match(t.host.textContent,/Asked for a thinking hint/);cleanup();t.dom.window.close();});
test('a finished round stays visible on reload until an explicit replay',()=>{const t=setup();t.cleanup();saveChoices(t.dom.window.localStorage,[complete(9)]);const cleanup=mountChoices(t.host,{storage:t.dom.window.localStorage});assert.match(t.host.textContent,/1\/10/);assert.ok(t.host.querySelector('[data-cc-restart]'));assert.equal(loadChoices(t.dom.window.localStorage).length,1);t.click('[data-cc-restart]');assert.match(t.host.textContent,/STORY 1 OF 10/);assert.equal(loadChoices(t.dom.window.localStorage).length,2);cleanup();t.dom.window.close();});
test('attempt limit offers a fresh round and keeps old evidence',()=>{const t=setup();t.cleanup();let state=createChoices();for(let i=0;i<120;i++)state=choose(state,'bin').state;saveChoices(t.dom.window.localStorage,[state]);const cleanup=mountChoices(t.host,{storage:t.dom.window.localStorage});assert.match(t.host.textContent,/Time for a fresh round/);t.click('[data-cc-restart]');assert.match(t.host.textContent,/STORY 1 OF 10/);assert.equal(loadChoices(t.dom.window.localStorage)[0].attempts.length,120);cleanup();t.dom.window.close();});
test('completion still explains a failed save',()=>{const t=setup();t.cleanup();const failed={getItem:()=>JSON.stringify({version:1,sessions:[complete()]}),setItem(){throw Error('full');}};const cleanup=mountChoices(t.host,{storage:failed});assert.match(t.host.textContent,/could not save your round/);assert.doesNotMatch(t.host.textContent,/choices are saved/);cleanup();t.dom.window.close();});
